import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import react from '@astrojs/react';
import rehypeAcronyms from './src/lib/rehype-acronyms.mjs';

const page = (label, slug) => ({ label, slug });

/** Every project has the same sections, grouped the way an architect reads a system:
 *  understand it → look inside the code → see the decisions → learn from its history. */
function project(label, id, { dataJourney = false, api = true } = {}) {
  return {
    label,
    items: [
      {
        label: 'Understand the system',
        items: [
          page('Overview', id),
          page('Quality attributes', `${id}/quality`),
          page('Architecture (C4 levels)', `${id}/architecture`),
          ...(dataJourney ? [page('A crash’s journey', `${id}/data-journey`)] : []),
        ],
      },
      {
        label: 'Inside the code',
        items: [
          page('Walkthroughs', `${id}/walkthroughs`),
          page('Code reference', `${id}/code`),
          ...(api ? [page('API reference', `${id}/api`)] : []),
          page('Algorithms & data science', `${id}/algorithms`),
          page('Design patterns', `${id}/patterns`),
        ],
      },
      {
        label: 'Decisions',
        items: [
          page('Decisions: you choose', `${id}/decisions`),
          page('Trade-offs: why this, not that', `${id}/tradeoffs`),
          page('Tech stack', `${id}/stack`),
        ],
      },
      {
        label: 'Learn & history',
        items: [
          page('Concepts in this project', `${id}/concepts`),
          page('Journey', `${id}/journey`),
          {
            label: 'Original records',
            collapsed: true,
            items: [
              page('All records', `${id}/records`),
              { label: 'Architecture Decision Records', collapsed: true, items: [{ autogenerate: { directory: `${id}/records/decisions` } }] },
              { label: 'Development log', collapsed: true, items: [{ autogenerate: { directory: `${id}/records/devlog` } }] },
            ],
          },
        ],
      },
    ],
  };
}

export default defineConfig({
  site: 'https://mdnoman1538.github.io',
  base: '/ai-driven-development-learning',
  markdown: { rehypePlugins: [rehypeAcronyms] },
  integrations: [
    starlight({
      title: 'AI Driven Development Learning',
      description: 'Learn software architecture and AI-driven development through real projects: the reasoning, the code and the decisions behind them.',
      logo: { src: './src/assets/logo.svg', replacesTitle: false },
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/MdNoman1538/ai-driven-development-learning' }],
      customCss: ['./src/styles/custom.css'],
      routeMiddleware: './src/routeData.ts',
      lastUpdated: true,
      sidebar: [
        project('Road Risk', 'road-risk', { dataJourney: true }),
        project('projectViewer', 'project-viewer'),
        project('This learning app', 'learning-app', { api: false }),
        {
          label: 'Combined knowledge',
          items: [
            page('Overview', 'knowledge'),
            {
              label: 'Start here',
              items: [
                page('How to learn here', 'start/how-to-learn'),
                page('What is AI-driven development?', 'start/ai-driven-development'),
                page('How this site stays current', 'start/how-this-site-stays-current'),
              ],
            },
            {
              label: 'Architecture knowledge',
              items: [
                page('Architect’s competency map', 'knowledge/competencies'),
                page('Architecture styles', 'knowledge/styles'),
                page('Design pattern catalogue', 'knowledge/patterns'),
                page('Trade-off library', 'knowledge/tradeoffs'),
                page('Algorithms & data science', 'knowledge/algorithms'),
              ],
            },
            {
              label: 'Concepts',
              items: [page('Concept library', 'concepts'), { label: 'All concepts', collapsed: true, items: [{ autogenerate: { directory: 'concepts' } }] }],
            },
            {
              label: 'Across all projects',
              items: [page('Whole tech stack', 'stack'), page('The full journey', 'journey'), page('Glossary', 'glossary')],
            },
          ],
        },
      ],
    }),
    react(),
  ],
});

// Fails (exit 1) when the teaching layer is missing an explanation (ADR-0003):
//   - a dependency of any project that no tool card covers
//   - an ADR of any project without a decision card (and decision cards for ADRs that don't exist)
//   - journey links to decisions or concepts that don't exist; glossary links to missing concepts
//   - a decision card whose `chosen` index points outside its options
// Run with `npm run coverage` (CI runs it on every PR).

import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import YAML from 'yaml';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => YAML.parse(readFileSync(join(ROOT, p), 'utf8'));
const facts = JSON.parse(readFileSync(join(ROOT, 'src/generated/sources.json'), 'utf8'));
const tools = read('src/data/tools.yaml');
const decisions = read('src/data/decisions.yaml');
const journey = read('src/data/journey.yaml');
const glossary = read('src/data/glossary.yaml');
const conceptExists = (slug) => existsSync(join(ROOT, 'src/content/docs/concepts', `${slug}.mdx`));

const problems = [];
const explained = new Set(tools.flatMap((t) => t.packages ?? []));

for (const [project, f] of Object.entries(facts)) {
  for (const dep of f.dependencies)
    if (!explained.has(dep.name)) problems.push(`${project}: dependency "${dep.name}" (${dep.file}) has no tool card. Add it to a card's packages in src/data/tools.yaml.`);

  const refs = new Set(decisions.filter((d) => d.project === project).map((d) => d.ref));
  for (const adr of f.records.decisions) {
    const ref = `ADR-${String(adr.number).padStart(4, '0')}`;
    if (!refs.has(ref)) problems.push(`${project}: ${ref} "${adr.title}" has no decision card in src/data/decisions.yaml.`);
  }
  const real = new Set(f.records.decisions.map((a) => `ADR-${String(a.number).padStart(4, '0')}`));
  for (const ref of refs) if (!real.has(ref)) problems.push(`${project}: decision card ${ref} has no matching ADR in the project.`);
}

for (const d of decisions)
  if (d.chosen >= d.options.length) problems.push(`decision ${d.id}: chosen=${d.chosen} but only ${d.options.length} options.`);

const decisionIds = new Set(decisions.map((d) => d.id));
for (const s of journey) {
  for (const id of s.decided ?? []) if (!decisionIds.has(id)) problems.push(`journey ${s.id}: unknown decision "${id}".`);
  for (const c of s.concepts ?? []) if (!conceptExists(c)) problems.push(`journey ${s.id}: unknown concept "${c}".`);
}
for (const g of glossary) if (g.concept && !conceptExists(g.concept)) problems.push(`glossary ${g.id}: unknown concept "${g.concept}".`);

// ---------------------------------------------------------------- code-level checks (L2)
const code = Object.fromEntries(
  Object.keys(facts).map((id) => [id, JSON.parse(readFileSync(join(ROOT, 'src/generated/code', `${id}.json`), 'utf8'))]),
);
const norm = (t) => t.replace(/\s+/g, ' ').trim();
const fileSource = (project, path) => code[project]?.files.find((f) => f.path === path)?.source ?? (project === 'learning-app' && existsSync(join(ROOT, path)) ? readFileSync(join(ROOT, path), 'utf8') : null);
function refExists(project, ref) {
  if (ref.includes('::')) return code[project]?.symbols.some((s) => s.id === ref);
  return fileSource(project, ref) !== null;
}
const read2 = (p) => read(p);
const projectsData = read2('src/data/projects.yaml');
const phases = Object.fromEntries(projectsData.map((p) => [p.id, new Set(p.phases.map((ph) => ph.id))]));
const stageOk = (project, stage, what) => {
  if (!phases[project]?.has(stage)) problems.push(`${what}: stage "${stage}" is not a phase of ${project}.`);
};
const checkRef = (project, ref, what) => {
  if (!refExists(project, ref)) problems.push(`${what}: "${ref}" doesn't exist in ${project}'s code. Renamed or removed? Update the reference.`);
};

for (const d of decisions) stageOk(d.project, d.stage, `decision ${d.id}`);
for (const q of read2('src/data/quality.yaml')) stageOk(q.project, q.stage, `quality ${q.id}`);

const styles = read2('src/data/styles.yaml');
const styleIds = new Set(styles.map((s) => s.id));
for (const p of projectsData) {
  for (const st of p.styles ?? []) if (!styleIds.has(st)) problems.push(`project ${p.id}: unknown style "${st}".`);
  for (const ph of p.phases) for (const c of ph.prepare ?? []) if (!conceptExists(c)) problems.push(`project ${p.id} phase ${ph.id}: unknown concept "${c}" to prepare.`);
  if (p.status_match && facts[p.id]?.status && !facts[p.id].status.includes(p.status_match))
    problems.push(`project ${p.id}: its status file says "${facts[p.id].status.slice(0, 80)}…", which no longer contains "${p.status_match}". The project has moved on: update its phases here.`);
}

const patterns = read2('src/data/patterns.yaml');
for (const pt of patterns) for (const u of pt.uses) { stageOk(u.project, u.stage, `pattern ${pt.id}`); checkRef(u.project, u.where, `pattern ${pt.id}`); }
const algorithms = read2('src/data/algorithms.yaml');
for (const a of algorithms) for (const u of a.uses) { stageOk(u.project, u.stage, `algorithm ${a.id}`); checkRef(u.project, u.where, `algorithm ${a.id}`); }
const tradeoffs = read2('src/data/tradeoffs.yaml');
for (const t of tradeoffs) { stageOk(t.project, t.stage, `trade-off ${t.id}`); for (const w of t.where ?? []) checkRef(t.project, w, `trade-off ${t.id}`); }

// Walkthrough snippets must still be in the code, word for word (whitespace aside).
const walkthroughs = read2('src/data/walkthroughs.yaml');
let snippets = 0;
for (const w of walkthroughs) {
  stageOk(w.project, w.stage, `walkthrough ${w.id}`);
  w.steps.forEach((step, i) => {
    checkRef(w.project, step.where, `walkthrough ${w.id} step ${i + 1}`);
    const src = fileSource(w.project, step.where.split('::')[0]);
    snippets++;
    if (src !== null && !norm(src).includes(norm(step.code)))
      problems.push(`walkthrough ${w.id} step ${i + 1}: the code snippet is no longer in ${step.where.split('::')[0]}:\n      ${norm(step.code).slice(0, 100)}`);
  });
}

// API: every Road Risk endpoint documented; every documented projectViewer route really served.
const api = read2('src/data/api.yaml');
for (const e of api) checkRef(e.project, e.handler, `api ${e.id}`);
for (const ep of code['road-risk'].endpoints)
  if (!api.some((a) => a.project === 'road-risk' && a.method === ep.method && a.path === ep.path)) problems.push(`road-risk: endpoint ${ep.method} ${ep.path} has no entry in src/data/api.yaml.`);
for (const a of api.filter((x) => x.project === 'road-risk'))
  if (!code['road-risk'].endpoints.some((ep) => ep.method === a.method && ep.path === a.path)) problems.push(`api ${a.id}: ${a.method} ${a.path} is not an endpoint in the code.`);
const pvServer = norm(fileSource('project-viewer', 'src/projectviewer/server.py') ?? '');
for (const a of api.filter((x) => x.project === 'project-viewer'))
  if (!pvServer.includes(`${a.method} ${a.path}`)) problems.push(`api ${a.id}: "${a.method} ${a.path}" isn't in projectViewer's route list (server.py).`);

// Concept uses and competency evidence.
const conceptFiles = readdirSync(join(ROOT, 'src/content/docs/concepts')).filter((f) => f.endsWith('.mdx'));
for (const f of conceptFiles) {
  const fm = YAML.parse(readFileSync(join(ROOT, 'src/content/docs/concepts', f), 'utf8').split('---')[1]);
  for (const [project, u] of Object.entries(fm.concept?.uses ?? {})) stageOk(project, u.stage, `concept ${f}`);
}
const refSets = {
  concept: (id) => conceptExists(id),
  decision: (id) => decisionIds.has(id),
  pattern: (id) => patterns.some((p) => p.id === id),
  tradeoff: (id) => tradeoffs.some((t) => t.id === id),
  algorithm: (id) => algorithms.some((a) => a.id === id),
  quality: (id) => read2('src/data/quality.yaml').some((q) => q.id === id),
  walkthrough: (id) => walkthroughs.some((w) => w.id === id),
  style: (id) => styleIds.has(id),
};
for (const area of read2('src/data/competencies.yaml'))
  for (const t of area.topics)
    for (const ev of t.evidence ?? []) {
      const [kind, id] = ev.split(':');
      if (!refSets[kind]?.(id)) problems.push(`competency ${area.id} / ${t.name}: unknown evidence "${ev}".`);
    }

// The playground must use the engine's real constants.
const model = JSON.parse(readFileSync(join(ROOT, 'src/data/risk-model.json'), 'utf8'));
const engineSrc = norm(fileSource('road-risk', model.file) ?? '');
for (const frag of model.source) if (!engineSrc.includes(norm(frag))) problems.push(`risk playground: "${frag}" is no longer in ${model.file}. Update src/data/risk-model.json.`);

const projects = Object.keys(facts);
const deps = projects.reduce((n, p) => n + facts[p].dependencies.length, 0);
const adrs = projects.reduce((n, p) => n + facts[p].records.decisions.length, 0);
if (problems.length) {
  console.error(`Coverage check failed: ${problems.length} problem(s)\n`);
  for (const p of problems) console.error(`  ✗ ${p}`);
  process.exit(1);
}
console.log(`Coverage OK across ${projects.length} projects: ${deps} dependencies, ${adrs} ADRs, ${api.length} API entries, ${walkthroughs.length} walkthroughs (${snippets} verified snippets), ${patterns.length} patterns, ${tradeoffs.length} trade-offs, ${algorithms.length} algorithms, ${journey.length} sessions, ${glossary.length} terms.`);

// Reads a TypeScript/JavaScript/Astro codebase into code facts (same shape as read_python.py).
//   node scripts/read-typescript.mjs <repo_dir> <out.json>
// Uses the TypeScript compiler's parser (no type-checking, no execution). Records functions,
// React components, classes and types with their parameters, defaults and doc comments, plus
// calls and JSX component uses it can resolve with certainty (same file or relative imports).

import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, extname, join, posix, relative } from 'node:path';
import ts from 'typescript';

const SKIP = new Set(['node_modules', 'dist', '.astro', '.cache', '.git', 'records', 'generated']);
const EXT = new Set(['.ts', '.tsx', '.mjs', '.js', '.astro']);

function walk(dir, root, out = []) {
  for (const name of readdirSync(dir)) {
    if (SKIP.has(name)) continue;
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, root, out);
    else if (EXT.has(extname(name)) && !name.endsWith('.d.ts')) out.push(relative(root, p).split('\\').join('/'));
  }
  return out;
}

const text = (node, sf) => (node ? node.getText(sf).replace(/\s+/g, ' ') : null);

function docOf(node, sf) {
  const full = sf.getFullText();
  const ranges = ts.getLeadingCommentRanges(full, node.getFullStart()) ?? [];
  const lines = ranges
    .map((r) => full.slice(r.pos, r.end))
    .map((c) => c.replace(/^\/\*\*?|\*\/$/g, '').replace(/^\s*\/\/ ?/gm, '').replace(/^\s*\* ?/gm, '').trim())
    .filter(Boolean);
  return lines.length ? lines.join('\n') : null;
}

function paramsOf(fn, sf) {
  return (fn.parameters ?? []).map((p) => {
    const out = { name: text(p.name, sf), type: text(p.type, sf) };
    if (p.initializer) out.default = text(p.initializer, sf);
    if (p.dotDotDotToken) out.kind = '...rest';
    return out;
  });
}

function read(root) {
  const files = [];
  const symbols = new Map();
  const pending = [];
  const sources = {};
  for (const rel of walk(root, root).sort()) {
    if (!(rel.startsWith('src/') || rel.startsWith('scripts/') || rel === 'astro.config.mjs')) continue;
    let source = readFileSync(join(root, rel), 'utf8');
    sources[rel] = source;
    let code = source;
    let offsetLines = 0;
    if (rel.endsWith('.astro')) {
      const m = source.match(/^---\n([\s\S]*?)\n---/);
      code = m ? m[1] : '';
      offsetLines = 1;
    }
    const kind = rel.endsWith('.tsx') ? ts.ScriptKind.TSX : rel.endsWith('.astro') || rel.endsWith('.ts') ? ts.ScriptKind.TS : ts.ScriptKind.JS;
    const sf = ts.createSourceFile(rel, code, ts.ScriptTarget.Latest, true, kind);
    const line = (n) => sf.getLineAndCharacterOfPosition(n.getStart(sf)).line + 1 + offsetLines;
    const endLine = (n) => sf.getLineAndCharacterOfPosition(n.getEnd()).line + 1 + offsetLines;
    const imports = {};
    files.push({ path: rel, doc: docOf(sf.statements[0] ?? sf, sf), loc: source.split('\n').length, source });

    const add = (name, node, fn, kindName, exported) => {
      const id = `${rel}::${name}`;
      symbols.set(id, {
        id,
        kind: kindName,
        name,
        qualname: name,
        file: rel,
        line: line(node),
        end_line: endLine(node),
        params: fn ? paramsOf(fn, sf) : [],
        returns: fn ? text(fn.type, sf) : null,
        async: !!fn?.modifiers?.some((m) => m.kind === ts.SyntaxKind.AsyncKeyword),
        exported,
        doc: docOf(node, sf),
      });
      if (fn) pending.push({ id, body: fn, sf, rel, imports });
    };

    if (rel.endsWith('.astro')) {
      add(posix.basename(rel, '.astro'), sf, null, 'component', true);
      // The HTML template (after the frontmatter) uses components as <Name …/> tags.
      const template = source.replace(/^---\n[\s\S]*?\n---/, '');
      pending.push({ id: `${rel}::${posix.basename(rel, '.astro')}`, tags: [...template.matchAll(/<([A-Z]\w*)/g)].map((m) => m[1]), rel, imports });
    }
    for (const st of sf.statements) {
      const exported = !!st.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword);
      if (ts.isImportDeclaration(st) && ts.isStringLiteral(st.moduleSpecifier)) {
        const spec = st.moduleSpecifier.text;
        if (!spec.startsWith('.')) continue;
        const target = resolveImport(root, rel, spec);
        const clause = st.importClause;
        if (clause?.name) imports[clause.name.text] = { file: target, name: 'default' };
        clause?.namedBindings?.elements?.forEach((el) => (imports[el.name.text] = { file: target, name: (el.propertyName ?? el.name).text }));
      } else if (ts.isFunctionDeclaration(st) && st.name) {
        const isComponent = rel.endsWith('.tsx') && /^[A-Z]/.test(st.name.text);
        add(st.name.text, st, st, isComponent ? 'component' : 'function', exported);
        if (st.modifiers?.some((m) => m.kind === ts.SyntaxKind.DefaultKeyword)) symbols.get(`${rel}::${st.name.text}`).default = true;
      } else if (ts.isVariableStatement(st)) {
        for (const d of st.declarationList.declarations) {
          if (ts.isIdentifier(d.name) && d.initializer && (ts.isArrowFunction(d.initializer) || ts.isFunctionExpression(d.initializer)))
            add(d.name.text, st, d.initializer, 'function', exported);
        }
      } else if (ts.isClassDeclaration(st) && st.name) {
        add(st.name.text, st, null, 'class', exported);
      } else if ((ts.isInterfaceDeclaration(st) || ts.isTypeAliasDeclaration(st)) && st.name) {
        add(st.name.text, st, null, 'type', exported);
      }
    }
  }

  // Resolve calls and JSX uses: same-file functions, or names imported from project files.
  const byFile = (file, name) => {
    if (name === 'default') {
      const inFile = [...symbols.values()].filter((s) => s.file === file);
      const stem = posix.basename(file).replace(/\.[^.]+$/, '');
      return (inFile.find((s) => s.default) ?? inFile.find((s) => s.name === stem) ?? inFile.find((s) => s.kind === 'component'))?.id;
    }
    return symbols.has(`${file}::${name}`) ? `${file}::${name}` : undefined;
  };
  for (const { id, body, sf, rel, imports, tags } of pending) {
    const calls = new Set();
    for (const name of tags ?? []) {
      const target = imports[name] ? byFile(imports[name].file, imports[name].name) : undefined;
      if (target && target !== id) calls.add(target);
    }
    if (!body) {
      symbols.get(id).calls = [...calls].sort();
      continue;
    }
    const visit = (n) => {
      let name = null;
      if (ts.isCallExpression(n) && ts.isIdentifier(n.expression)) name = n.expression.text;
      if ((ts.isJsxOpeningElement(n) || ts.isJsxSelfClosingElement(n)) && ts.isIdentifier(n.tagName)) name = n.tagName.text;
      if (name) {
        const target = symbols.has(`${rel}::${name}`) ? `${rel}::${name}` : imports[name] ? byFile(imports[name].file, imports[name].name) : undefined;
        if (target && target !== id) calls.add(target);
      }
      ts.forEachChild(n, visit);
    };
    ts.forEachChild(body, visit);
    symbols.get(id).calls = [...calls].sort();
  }
  for (const s of symbols.values()) for (const t of s.calls ?? []) (symbols.get(t).called_by ??= []).push(s.id);
  for (const s of symbols.values()) s.called_by = [...new Set(s.called_by ?? [])].sort();
  return { language: 'typescript', files, symbols: [...symbols.values()], endpoints: [] };
}

function resolveImport(root, from, spec) {
  const base = posix.normalize(posix.join(posix.dirname(from), spec));
  for (const cand of [base, `${base}.ts`, `${base}.tsx`, `${base}.mjs`, `${base}.js`, `${base}/index.ts`])
    if (existsSync(join(root, cand)) && statSync(join(root, cand)).isFile()) return cand;
  return base;
}

const [root, out] = process.argv.slice(2);
const facts = read(root);
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, JSON.stringify(facts, null, 1) + '\n');
console.log(`typescript: ${facts.files.length} files, ${facts.symbols.length} symbols`);

// Imports the "records" (ADRs, devlogs, roadmap, status) and the facts (dependencies, CI jobs,
// history) of every project in sources.config.json. Run with `npm run sync`.
//
// Why: the site must never disagree with the projects it teaches. Records are copied, not
// retyped, and facts are read from the projects' own files (ADR-0002, ADR-0003).
// Output is deterministic (no timestamps), so a sync that changes nothing produces no diff.

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, posix } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse as parseToml } from 'smol-toml';
import YAML from 'yaml';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CACHE = join(ROOT, '.cache', 'sources');
const DOCS = join(ROOT, 'src', 'content', 'docs');
const FACTS = join(ROOT, 'src', 'generated', 'sources.json');

// The site is public. Nothing private may pass through it (ADR-0004).
const FORBIDDEN = [
  [/\/Users\/[^/\s)`'"]+/g, 'a local home-directory path'],
  // example.com/.org/.net are reserved for documentation (RFC 2606), so they can't belong to anyone.
  [/(?<![\w.`])[\w.%+-]+@(?!anthropic\.com\b|example\.(?:com|org|net)\b)[\w-]+(\.[\w-]+)*\.[a-z]{2,}\b/gi, 'an email address'],
];

const git = (cwd, ...args) => execFileSync('git', args, { cwd, encoding: 'utf8' }).trim();

function checkout(source) {
  if (source.self) return ROOT;
  const dir = join(CACHE, source.id);
  if (existsSync(join(dir, '.git'))) {
    git(dir, 'fetch', '--quiet', 'origin', 'main');
    git(dir, 'reset', '--quiet', '--hard', 'origin/main');
  } else {
    mkdirSync(CACHE, { recursive: true });
    // Full history (for commit counts) but file contents only on demand: small and fast.
    execFileSync('git', ['clone', '--quiet', '--filter=blob:none', `${source.repo}.git`, dir]);
  }
  return dir;
}

function guard(text, where) {
  for (const [pattern, what] of FORBIDDEN) {
    const hit = text.match(pattern);
    if (hit) throw new Error(`${where} contains ${what} (${hit[0]}). Fix it in the source repo first.`);
  }
  return text;
}

function rewriteLinks(body, source, repoDir, fileRel) {
  // Relative links point into the source repo; on this site they must point at GitHub.
  return body.replace(/\]\(([^)\s]+)\)/g, (match, target) => {
    if (/^(https?:|mailto:|#)/.test(target)) return match;
    const [path, hash = ''] = target.split('#');
    const resolved = posix.normalize(posix.join(posix.dirname(fileRel), path));
    const abs = join(repoDir, resolved);
    const kind = existsSync(abs) && statSync(abs).isDirectory() ? 'tree' : 'blob';
    return `](${source.repo}/${kind}/main/${resolved}${hash ? `#${hash}` : ''})`;
  });
}

function recordFiles(repoDir, entry) {
  const abs = join(repoDir, entry);
  if (!existsSync(abs)) return [];
  if (statSync(abs).isFile()) return [entry];
  return readdirSync(abs)
    .filter((f) => f.endsWith('.md') && !['template.md', 'README.md'].includes(f))
    .sort()
    .map((f) => posix.join(entry, f));
}

function importRecord(source, repoDir, fileRel, commit) {
  const raw = guard(readFileSync(join(repoDir, fileRel), 'utf8'), `${source.id}:${fileRel}`);
  const name = basename(fileRel, '.md');
  const kind = fileRel.includes('/decisions/') ? 'decisions' : fileRel.includes('/devlog/') ? 'devlog' : 'overview';
  const heading = raw.match(/^# (.+)$/m)?.[1]?.trim() ?? name;
  const body = rewriteLinks(raw.replace(/^# .+\n/m, ''), source, repoDir, fileRel);

  const meta = { kind, slug: `${source.id}/records/${kind === 'overview' ? name : `${kind}/${name}`}` };
  let order = 1;
  if (kind === 'decisions') {
    meta.number = Number(name.slice(0, 4));
    meta.status = raw.match(/^- \*\*Status:\*\*\s*(.+)$/m)?.[1]?.trim() ?? 'Unknown';
    meta.date = raw.match(/^- \*\*Date:\*\*\s*(\S+)/m)?.[1] ?? null;
    order = meta.number;
  } else if (kind === 'devlog') {
    meta.date = name.slice(0, 10);
    order = Number(meta.date.replaceAll('-', ''));
  } else {
    order = ['roadmap', 'project-status', 'architecture'].indexOf(name) + 1;
  }
  meta.title = heading;

  const sourceUrl = `${source.repo}/blob/main/${fileRel}`;
  const frontmatter = {
    title: heading,
    sidebar: { order, label: kind === 'decisions' ? heading.replace(/^ADR-(\d+):\s*/, '$1 · ') : heading },
    record: { project: source.id, kind, source: sourceUrl, commit },
  };
  const note = `:::note[Original record]\nImported unchanged from [\`${fileRel}\`](${sourceUrl}) at commit \`${commit}\`. It is the project's own record; the teaching pages explain it.\n:::\n`;
  const out = join(DOCS, `${meta.slug}.md`);
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, `---\n${YAML.stringify(frontmatter)}---\n\n${note}\n${body.trim()}\n`);
  return meta;
}

const depName = (spec) => spec.split(/[<>=!~\s[;]/)[0].trim().toLowerCase();

function pythonDeps(repoDir, files) {
  const deps = [];
  let requires = null;
  for (const f of files) {
    const toml = parseToml(readFileSync(join(repoDir, f), 'utf8'));
    requires ??= toml.project?.['requires-python'] ?? null;
    for (const spec of toml.project?.dependencies ?? []) deps.push({ name: depName(spec), spec, group: 'runtime', file: f });
    for (const [group, specs] of Object.entries(toml['dependency-groups'] ?? {}))
      for (const spec of specs) if (typeof spec === 'string') deps.push({ name: depName(spec), spec, group, file: f });
  }
  return { requires, deps };
}

function nodeDeps(repoDir, files) {
  const deps = [];
  for (const f of files) {
    const pkg = JSON.parse(readFileSync(join(repoDir, f), 'utf8'));
    for (const [name, version] of Object.entries(pkg.dependencies ?? {})) deps.push({ name, version, group: 'runtime', file: f });
    for (const [name, version] of Object.entries(pkg.devDependencies ?? {})) deps.push({ name, version, group: 'dev', file: f });
  }
  return deps;
}

function workflows(repoDir, files) {
  return files
    .filter((f) => existsSync(join(repoDir, f)))
    .map((f) => {
      const wf = YAML.parse(readFileSync(join(repoDir, f), 'utf8'));
      const jobs = Object.entries(wf.jobs ?? {}).map(([id, job]) => job.name ?? id);
      const actions = [...readFileSync(join(repoDir, f), 'utf8').matchAll(/uses:\s*([\w./-]+)@([\w.-]+)/g)].map((m) => `${m[1]}@${m[2]}`);
      return { file: f, name: wf.name ?? f, jobs, actions: [...new Set(actions)].sort() };
    });
}

function history(repoDir) {
  const subjects = git(repoDir, 'log', '--format=%s').split('\n').filter(Boolean);
  const dates = git(repoDir, 'log', '--format=%cs').split('\n').filter(Boolean);
  return {
    commits: subjects.length,
    mergedPullRequests: subjects.filter((s) => /^Merge pull request #\d+/.test(s)).length,
    firstCommit: dates.at(-1) ?? null,
    lastCommit: dates[0] ?? null,
  };
}

// Code facts (modules, classes, functions, parameters, calls, endpoints) for the code reference,
// walkthroughs and the build's snippet checks. Python is read with Python's own parser.
function readCode(source, repoDir) {
  const out = join(ROOT, 'src', 'generated', 'code', `${source.id}.json`);
  if (source.code === 'python') execFileSync('python3', [join(ROOT, 'scripts', 'read_python.py'), repoDir, out], { stdio: 'inherit' });
  else if (source.code === 'typescript') execFileSync('node', [join(ROOT, 'scripts', 'read-typescript.mjs'), repoDir, out], { stdio: 'inherit' });
  const facts = JSON.parse(readFileSync(out, 'utf8'));
  // Extra parts in another language (e.g. projectViewer's JavaScript viewer), merged with a path prefix.
  for (const extra of source.extraCode ?? []) {
    const tmp = join(ROOT, '.cache', `${source.id}-${extra.dir}.json`);
    execFileSync('node', [join(ROOT, 'scripts', 'read-typescript.mjs'), join(repoDir, extra.dir), tmp], { stdio: 'inherit' });
    const more = JSON.parse(readFileSync(tmp, 'utf8'));
    const pre = (id) => `${extra.dir}/${id}`;
    for (const f of more.files) facts.files.push({ ...f, path: pre(f.path) });
    for (const s of more.symbols)
      facts.symbols.push({ ...s, id: pre(s.id), file: pre(s.file), calls: s.calls.map(pre), called_by: s.called_by.map(pre) });
    writeFileSync(out, JSON.stringify(facts, null, 1) + '\n');
  }
  for (const f of facts.files) guard(f.source, `${source.id}:${f.path}`);
}

/** The project's own "current phase" line, so the site can tell when a project has moved on. */
function statusLine(repoDir) {
  const p = join(repoDir, 'docs', 'project-status.md');
  if (!existsSync(p)) return null;
  const line = readFileSync(p, 'utf8').split('\n').find((l) => /\*\*(Current phase|Phase):\*\*/.test(l));
  return line ? line.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/\*\*/g, '').trim() : null;
}

const config = JSON.parse(readFileSync(join(ROOT, 'sources.config.json'), 'utf8'));
const facts = {};
for (const source of config.sources) {
  const repoDir = checkout(source);
  const commit = git(repoDir, 'rev-parse', '--short', 'HEAD');
  rmSync(join(DOCS, source.id, 'records'), { recursive: true, force: true });
  const records = { decisions: [], devlog: [], overview: [] };
  for (const entry of source.records)
    for (const fileRel of recordFiles(repoDir, entry)) {
      const meta = importRecord(source, repoDir, fileRel, commit);
      records[meta.kind].push(meta);
    }
  readCode(source, repoDir);
  const py = pythonDeps(repoDir, source.python);
  facts[source.id] = {
    repo: source.repo,
    commit,
    ...history(repoDir),
    python: py.requires,
    dependencies: [...py.deps.map((d) => ({ ...d, ecosystem: 'python' })), ...nodeDeps(repoDir, source.node).map((d) => ({ ...d, ecosystem: 'node' }))],
    workflows: workflows(repoDir, source.workflows),
    status: statusLine(repoDir),
    records,
  };
  const n = records.decisions.length + records.devlog.length + records.overview.length;
  console.log(`${source.id.padEnd(15)} ${commit}  ${n} records, ${facts[source.id].dependencies.length} dependencies, ${facts[source.id].commits} commits`);
}
mkdirSync(dirname(FACTS), { recursive: true });
writeFileSync(FACTS, JSON.stringify(facts, null, 2) + '\n');
console.log(`wrote ${FACTS.replace(ROOT + '/', '')}`);

