// Finds acronyms in text and decides where to spell them out. Shared by the page plugin
// (rehype-acronyms.mjs) and the interactive components (Inline.tsx), so both behave the same.
import list from '../data/acronyms.json' with { type: 'json' };

export const ACRONYMS = Object.fromEntries(Object.entries(list).filter(([k]) => !k.startsWith('$')));

const escape = (s) => s.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
const alternation = Object.keys(ACRONYMS).sort((a, b) => b.length - a.length).map(escape).join('|');
// Whole words only (not inside other words), optional plural "s".
const PATTERN = new RegExp(`(?<![A-Za-z0-9_\\-])(${alternation})(s?)(?![A-Za-z0-9_])`, 'g');

/**
 * Splits text into plain strings and acronym parts.
 * `seen` is the set of acronyms already spelled out in this scope (a page, or a card);
 * the first use in a scope gets `expand: true` unless the text already spells it out.
 */
export function splitAcronyms(text, seen) {
  const parts = [];
  let last = 0;
  for (const m of text.matchAll(PATTERN)) {
    const [whole, short, plural] = m;
    const at = m.index;
    if (at > last) parts.push(text.slice(last, at));
    const after = text.slice(at + whole.length);
    const alreadySpelled = /^\s*\(/.test(after);
    const glued = /^[:\-]\w/.test(after); // part of an identifier such as EPSG:3067
    const expand = !seen.has(short) && !alreadySpelled && !glued;
    if (!glued) seen.add(short);
    parts.push({ short: whole, full: ACRONYMS[short] + (plural ? 's' : ''), expand });
    last = at + whole.length;
  }
  if (last < text.length) parts.push(text.slice(last));
  return parts;
}

const html = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** HTML for Astro components: <abbr> everywhere, spelled out on first use in `seen`. */
export function acronymHtml(text, seen) {
  return splitAcronyms(text, seen)
    .map((p) => (typeof p === 'string' ? html(p) : `<abbr title="${html(p.full)}">${html(p.short)}</abbr>${p.expand ? ` (${html(p.full)})` : ''}`))
    .join('');
}

// The site's areas: one per project, plus the shared "Combined knowledge".
export type AreaId = 'road-risk' | 'project-viewer' | 'learning-app' | 'knowledge';

export const AREAS: Record<AreaId, { label: string; accent: { dark: string; light: string } }> = {
  'road-risk': { label: 'Road Risk', accent: { dark: '#f59e0b', light: '#b45309' } },
  'project-viewer': { label: 'projectViewer', accent: { dark: '#a78bfa', light: '#6d28d9' } },
  'learning-app': { label: 'This learning app', accent: { dark: '#2dd4bf', light: '#0f766e' } },
  knowledge: { label: 'Combined knowledge', accent: { dark: '#60a5fa', light: '#1d4ed8' } },
};

/** Pages under these top-level folders belong to Combined knowledge. */
const KNOWLEDGE = new Set(['knowledge', 'concepts', 'glossary', 'stack', 'journey', 'start']);

export function areaOf(id: string): AreaId | null {
  const top = id.split('/')[0];
  if (top in AREAS && top !== 'knowledge') return top as AreaId;
  return KNOWLEDGE.has(top) ? 'knowledge' : null;
}

// Where each kind of teaching item lives on the site, so any reference can become a link.
import { href } from './site';

export function refLink(ref: string, projectOf: (kind: string, id: string) => string | undefined): { href: string; label: string } | null {
  const [kind, id] = ref.split(':');
  const project = projectOf(kind, id);
  switch (kind) {
    case 'concept': return { href: href(`concepts/${id}`), label: id };
    case 'pattern': return { href: href(`knowledge/patterns#${id}`), label: id };
    case 'algorithm': return { href: href(`knowledge/algorithms#${id}`), label: id };
    case 'style': return { href: href(`knowledge/styles#${id}`), label: id };
    case 'decision': return project ? { href: href(`${project}/decisions#${id}`), label: id } : null;
    case 'tradeoff': return project ? { href: href(`${project}/tradeoffs#${id}`), label: id } : null;
    case 'quality': return project ? { href: href(`${project}/quality#${id}`), label: id } : null;
    case 'walkthrough': return project ? { href: href(`${project}/walkthroughs#${id}`), label: id } : null;
    default: return null;
  }
}

/** GitHub link to a code reference "file::Name" (line from the code facts when known). */
export function githubLink(repo: string, file: string, line?: number): string {
  return `${repo}/blob/main/${file}${line ? `#L${line}` : ''}`;
}

// Build-time plugin for every Markdown/MDX page, including imported records:
// wraps acronyms in <abbr title="full form"> and spells out the first use on each page.
import { splitAcronyms } from './acronyms.mjs';

const SKIP = new Set(['code', 'pre', 'kbd', 'samp', 'abbr', 'script', 'style', 'svg', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6']);

export default function rehypeAcronyms() {
  return (tree) => {
    const seen = new Set();
    const walk = (node) => {
      if (!node.children) return;
      const out = [];
      for (const child of node.children) {
        if (child.type === 'text') {
          for (const p of splitAcronyms(child.value, seen)) {
            if (typeof p === 'string') out.push({ type: 'text', value: p });
            else {
              out.push({ type: 'element', tagName: 'abbr', properties: { title: p.full }, children: [{ type: 'text', value: p.short }] });
              if (p.expand) out.push({ type: 'text', value: ` (${p.full})` });
            }
          }
        } else {
          // Skip code, headings and embedded components (they handle acronyms themselves).
          if (!(child.type === 'element' && SKIP.has(child.tagName)) && !String(child.type).startsWith('mdxJsx')) walk(child);
          out.push(child);
        }
      }
      node.children = out;
    };
    walk(tree);
  };
}

// Shared helpers for components.

/** A link inside the site that respects the GitHub Pages base path. */
export function href(path: string): string {
  const base = import.meta.env.BASE_URL.replace(/\/$/, '');
  const clean = path.replace(/^\//, '');
  return `${base}/${clean}${clean && !clean.includes('#') && !clean.endsWith('/') ? '/' : ''}`;
}

export const PROJECT_NAMES: Record<string, string> = {
  'road-risk': 'Road Risk',
  'project-viewer': 'projectViewer',
  'learning-app': 'Learning app',
};

export const LAYER_NAMES: Record<string, string> = {
  language: 'Languages',
  data: 'Data',
  backend: 'Backend',
  frontend: 'Frontend',
  testing: 'Testing',
  quality: 'Code quality',
  workflow: 'Workflow',
  delivery: 'Delivery',
  ai: 'AI',
};

// Build-time helpers shared by the project pages.
import { getCollection } from 'astro:content';
import { href } from './site';

export const codeHref = (project: string, where: string) => href(`${project}/code#${encodeURIComponent(where)}`);

export async function stageNames(project: string): Promise<Record<string, string>> {
  const p = (await getCollection('projects')).find((e) => e.data.id === project)!.data;
  return Object.fromEntries(p.phases.map((ph) => [ph.id, ph.name]));
}

/** symbol id → the teaching pages that explain it ("Explained in" on the code reference). */
export async function taughtIndex(project: string) {
  const out: Record<string, { label: string; href: string }[]> = {};
  const add = (where: string, label: string, link: string) => (out[where] ??= []).push({ label, href: link });
  for (const { data: w } of await getCollection('walkthroughs')) {
    if (w.project !== project) continue;
    const steps = new Map<string, number[]>();
    w.steps.forEach((s, i) => steps.set(s.where, [...(steps.get(s.where) ?? []), i + 1]));
    for (const [where, nums] of steps) add(where, `Walkthrough: ${w.title} (step${nums.length > 1 ? 's' : ''} ${nums.join(', ')})`, href(`${project}/walkthroughs#${w.id}`));
  }
  for (const { data: p } of await getCollection('patterns'))
    for (const u of p.uses) if (u.project === project) add(u.where, `Pattern: ${p.name}`, href(`${project}/patterns#${p.id}`));
  for (const { data: a } of await getCollection('algorithms'))
    for (const u of a.uses) if (u.project === project) add(u.where, `Algorithm: ${a.name}${u.status === 'planned' ? ' (planned, will replace this)' : ''}`, href(`${project}/algorithms#${a.id}`));
  for (const { data: t } of await getCollection('tradeoffs'))
    if (t.project === project) for (const w of t.where) add(w, `Trade-off: ${t.question}`, href(`${project}/tradeoffs#${t.id}`));
  return out;
}

/** 1-based line where a snippet starts in a file (for exact GitHub links). */
export function lineOf(source: string, snippet: string): number | undefined {
  const first = snippet.trim().split('\n')[0].trim();
  const i = source.split('\n').findIndex((l) => l.includes(first));
  return i >= 0 ? i + 1 : undefined;
}

// Server-side rendering of the small Markdown subset used in data files, with acronym expansion.
// Pass one `seen` set per card/section: the first use of an acronym in it is spelled out.
import { acronymHtml } from './acronyms.mjs';

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

export function md(text: string, seen: Set<string> = new Set()): string {
  let out = '';
  let last = 0;
  for (const m of text.matchAll(/(`[^`]+`|\*\*[^*]+\*\*|\*[^*]+\*)/g)) {
    const at = m.index ?? 0;
    out += acronymHtml(text.slice(last, at), seen);
    const t = m[0];
    if (t.startsWith('`')) out += `<code>${esc(t.slice(1, -1))}</code>`;
    else if (t.startsWith('**')) out += `<strong>${acronymHtml(t.slice(2, -2), seen)}</strong>`;
    else out += `<em>${acronymHtml(t.slice(1, -1), seen)}</em>`;
    last = at + t.length;
  }
  return out + acronymHtml(text.slice(last), seen);
}

// Static JSON per project, written at build time: the code reference loads it only when opened,
// so pages stay light even though a project's full source is several hundred KB.
import type { APIRoute, GetStaticPaths } from 'astro';
import facts from '../../generated/sources.json';

export const getStaticPaths: GetStaticPaths = () => Object.keys(facts).map((project) => ({ params: { project } }));

export const GET: APIRoute = async ({ params }) => {
  const mod = await import(`../../generated/code/${params.project}.json`);
  const data = mod.default;
  const repo = (facts as Record<string, { repo: string; commit: string }>)[params.project as string];
  return new Response(JSON.stringify({ ...data, repo: repo.repo, commit: repo.commit }), { headers: { 'Content-Type': 'application/json' } });
};

// Scoped navigation: inside a project you see only that project; the shared material lives in
// "Combined knowledge". The full sidebar is defined once in astro.config.mjs; this middleware
// keeps only the current area's group, and limits previous/next links to that area.
import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { AREAS, areaOf } from './lib/areas';

type Entry = { type: 'link' | 'group'; label: string; href?: string; isCurrent?: boolean; entries?: Entry[] };

function flatten(entries: Entry[]): Entry[] {
  return entries.flatMap((e) => (e.type === 'group' ? flatten(e.entries ?? []) : [e]));
}

export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  const area = areaOf(route.id);
  if (!area) return;
  const group = (route.sidebar as Entry[]).find((e) => e.type === 'group' && e.label === AREAS[area].label);
  if (!group) return;

  const home: Entry = { type: 'link', label: 'All projects', href: `${import.meta.env.BASE_URL.replace(/\/$/, '')}/`, isCurrent: false };
  route.sidebar = [
    { ...home, badge: undefined, attrs: { class: 'lx-nav-home' } },
    ...(group.entries ?? []),
  ] as typeof route.sidebar;

  const pages = flatten(group.entries ?? []);
  const i = pages.findIndex((p) => p.isCurrent);
  route.pagination = {
    prev: i > 0 ? (pages[i - 1] as never) : undefined,
    next: i >= 0 && i < pages.length - 1 ? (pages[i + 1] as never) : undefined,
  };

  // Each area has its own accent colour, so you always know where you are.
  const { dark, light } = AREAS[area].accent;
  route.head.push({
    tag: 'style',
    attrs: {},
    content: `html:root:root, html:root[data-theme='dark']{--sl-color-accent:${dark};--lx-area:${dark}} html:root[data-theme='light']{--sl-color-accent:${light};--lx-area:${light}}`,
  });
});

